import { parse, NodeType } from 'node-html-parser';

/**
 * Allowlist-based HTML sanitizer.
 *
 * - Allowed tags: p, br, b, i, em, strong, a, ul, ol, li, code, pre, blockquote
 * - Allowed attributes: only `href` on <a>, and only if its scheme (after HTML
 *   entity decoding + whitespace/control stripping) is http, https or mailto.
 * - Disallowed elements are unwrapped: dropped, but their text content kept.
 *   Exception: <script> and <style> are dropped entirely, content included.
 * - Comments are removed. `on*` attributes, `style` attributes and `srcdoc`
 *   can never survive (nothing but a[href] survives at all).
 */

const ALLOWED_TAGS = new Set([
  'p', 'br', 'b', 'i', 'em', 'strong', 'a',
  'ul', 'ol', 'li', 'code', 'pre', 'blockquote',
]);

const VOID_TAGS = new Set(['br']);
const DROP_ENTIRELY_TAGS = new Set(['script', 'style']);

const ALLOWED_HREF_SCHEME_RE = /^(?:https?|mailto):/i;

// Named entities relevant to scheme smuggling / URL construction.
const NAMED_ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'",
  colon: ':', semi: ';', sol: '/', bsol: '\\',
  nbsp: '\u00a0', Tab: '\t', NewLine: '\n',
  excl: '!', num: '#', lpar: '(', rpar: ')', plus: '+',
  comma: ',', period: '.', hyphen: '-', quest: '?', equals: '=',
  commat: '@', colon_etc: undefined,
};

/** Decode named & numeric character references once (browser-like). */
function decodeEntities(input) {
  return input.replace(
    /&(#[xX][0-9a-fA-F]+|#[0-9]+|[a-zA-Z][a-zA-Z0-9]*);?/g,
    (match, body) => {
      if (body.startsWith('#')) {
        const code = /^#[xX]/.test(body)
          ? parseInt(body.slice(2), 16)
          : parseInt(body.slice(1), 10);
        if (!Number.isFinite(code) || code < 0 || code > 0x10ffff) return match;
        try {
          return String.fromCodePoint(code);
        } catch {
          return match;
        }
      }
      const named = NAMED_ENTITIES[body] ?? NAMED_ENTITIES[body.toLowerCase()];
      return named !== undefined ? named : match;
    }
  );
}

/**
 * Decide whether an href value is safe under the scheme allowlist.
 * Mirrors browser URL preprocessing: decode entities, strip tab/CR/LF
 * anywhere, then strip leading/trailing C0 controls and spaces before
 * checking the scheme.
 */
export function isSafeHref(raw) {
  if (typeof raw !== 'string') return false;
  let value = decodeEntities(raw);
  // Browsers strip \t \r \n from URLs wherever they occur.
  value = value.replace(/[\t\r\n]/g, '');
  // Strip leading/trailing C0 controls and space (URL parser trims these).
  value = value.replace(/^[\u0000-\u0020]+/, '').replace(/[\u0000-\u0020]+$/, '');
  // Paranoid extra: remove remaining C0/C1 controls anywhere before the first
  // colon so e.g. "java\u0001script:" cannot smuggle through.
  const colonIdx = value.indexOf(':');
  if (colonIdx === -1) {
    // No scheme at all (relative URL, fragment, etc.) -> not allowlisted.
    return false;
  }
  const schemePart = value.slice(0, colonIdx).replace(/[\u0000-\u001f\u007f-\u009f]/g, '');
  return ALLOWED_HREF_SCHEME_RE.test(`${schemePart}:`);
}

function escapeText(text) {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escapeAttr(text) {
  return escapeText(text).replace(/"/g, '&quot;');
}

/** Recursively rebuild clean markup from the parsed tree. */
function serializeNode(node) {
  let out = '';
  for (const child of node.childNodes ?? []) {
    switch (child.nodeType) {
      case NodeType.COMMENT_NODE:
        continue; // comments never survive
      case NodeType.TEXT_NODE:
        // `.text` gives the decoded text; re-escape it for output.
        out += escapeText(child.text);
        continue;
      case NodeType.ELEMENT_NODE:
        break;
      default:
        continue;
    }

    const tag = (child.rawTagName || '').toLowerCase();

    if (!ALLOWED_TAGS.has(tag)) {
      if (DROP_ENTIRELY_TAGS.has(tag)) {
        continue; // script/style: drop element *and* its content
      }
      out += serializeNode(child); // unwrap: keep children/text only
      continue;
    }

    // Allowed tag: rebuild it from scratch with no inherited attributes.
    if (VOID_TAGS.has(tag)) {
      out += `<${tag}>`;
      continue;
    }

    let attrs = '';
    if (tag === 'a') {
      const href = child.getAttribute('href');
      if (typeof href === 'string' && isSafeHref(href)) {
        attrs = ` href="${escapeAttr(href.trim())}"`;
      }
    }
    out += `<${tag}${attrs}>`;
    out += serializeNode(child);
    out += `</${tag}>`;
  }
  return out;
}

/** Sanitize an HTML string into a safe HTML string. */
export function sanitize(html) {
  const root = parse(String(html ?? ''), {
    lowerCaseTagName: true,
    comment: true, // keep comments in the tree so we control their removal
    blockTextElements: { script: true, style: true, noscript: true },
  });
  return serializeNode(root);
}

