import { describe, it, expect } from 'vitest';
import { parse, NodeType } from 'node-html-parser';
import { sanitize } from '../src/sanitizer.js';

/**
 * Re-parse sanitizer output with an independent parse pass and reduce it to a
 * normalized tree: [{ tag, attrs: {...}, children: [...] , texts: [...] }]
 * Comments are surfaced as null so we can assert their absence explicitly.
 */
function toTree(html) {
  const root = parse(html, { comment: true });
  function walk(node) {
    const out = [];
    for (const child of node.childNodes ?? []) {
      if (child.nodeType === NodeType.COMMENT_NODE) {
        out.push(null); // any surviving comment becomes visible in the tree
        continue;
      }
      if (child.nodeType === NodeType.TEXT_NODE) {
        if (child.text.trim() !== '') out.push({ text: child.text });
        continue;
      }
      if (child.nodeType !== NodeType.ELEMENT_NODE) continue;
      const attrs = {};
      for (const [k, v] of Object.entries(child.attributes ?? {})) attrs[k] = v;
      out.push({
        tag: child.rawTagName.toLowerCase(),
        attrs,
        children: walk(child),
      });
    }
    return out;
  }
  return walk(root);
}

describe('sanitize() — inline vector suite', () => {
  it('V01: simple allowed markup passes through intact', () => {
    const out = sanitize('<p>Hello <b>world</b></p>');
    expect(out).toBe('<p>Hello <b>world</b></p>');
    expect(toTree(out)).toEqual([
      { tag: 'p', attrs: {}, children: [
        { text: 'Hello ' },
        { tag: 'b', attrs: {}, children: [{ text: 'world' }] },
      ] },
    ]);
  });

  it('V02: script inside allowed element is dropped entirely, sibling text kept', () => {
    const out = sanitize('<b><script>x</script>bold</b>');
    expect(out).toBe('<b>bold</b>');
    expect(toTree(out)).toEqual([
      { tag: 'b', attrs: {}, children: [{ text: 'bold' }] },
    ]);
  });

  it('V03: mixed-case javascript: href is stripped but <a> kept', () => {
    const out = sanitize('<a HrEf="JaVaScRiPt:alert(1)">click</a>');
    expect(toTree(out)).toEqual([
      { tag: 'a', attrs: {}, children: [{ text: 'click' }] },
    ]);
  });

  it('V04: entity-encoded javascript: href is decoded before scheme check', () => {
    const out = sanitize('<a href="&#106;avascript&colon;alert(1)">x</a>');
    expect(toTree(out)).toEqual([{ tag: 'a', attrs: {}, children: [{ text: 'x' }] }]);
  });

  it('V05: whitespace/control chars embedded in the scheme are neutralized', () => {
    for (const payload of [
      '<a href="jav\tascript:alert(1)">x</a>',
      '<a href="jav&#x0A;ascript:alert(1)">x</a>',
      '<a href=" &#14; javascript:alert(1)">x</a>',
      '<a href="java\x01script:alert(1)">x</a>',
    ]) {
      const out = sanitize(payload);
      expect(toTree(out)).toEqual([{ tag: 'a', attrs: {}, children: [{ text: 'x' }] }]);
    }
  });

  it('V06: allowlisted schemes survive with the attribute intact', () => {
    for (const href of [
      'http://example.com/a?b=c#d',
      'https://example.com',
      'mailto:user@example.com',
      'HTTPS://EXAMPLE.COM/UPPER',
      'MAILTO:User@Example.com',
    ]) {
      const out = sanitize(`<a href="${href}">ok</a>`);
      expect(toTree(out)).toEqual([
        { tag: 'a', attrs: { href: href.trim() }, children: [{ text: 'ok' }] },
      ]);
    }
  });

  it('V07: non-allowlisted schemes (vbscript, data, file, relative) lose href', () => {
    for (const href of [
      'vbscript:msgbox(1)',
      'data:text/html,<script>alert(1)</script>',
      'file:///etc/passwd',
      '/relative/path',
      '#fragment',
      '//protocol-relative.example.com',
    ]) {
      const out = sanitize(`<a href="${href}">y</a>`);
      expect(toTree(out)).toEqual([{ tag: 'a', attrs: {}, children: [{ text: 'y' }] }]);
    }
  });

  it('V08: event handlers never survive on kept or unwrapped elements', () => {
    const out = sanitize('<p onclick="evil()" onmouseover=steal()>hi</p><img src=x onerror="alert(1)">');
    expect(toTree(out)).toEqual([
      { tag: 'p', attrs: {}, children: [{ text: 'hi' }] },
    ]);
    // every on* attribute anywhere in the output tree
    const flat = JSON.stringify(toTree(out));
    expect(flat).not.toMatch(/on[a-z]+"/i);
  });

  it('V09: style attributes and style elements never survive', () => {
    const out = sanitize('<p style="color:red;background:url(javascript:x)">t</p><style>p{color:red}</style>');
    expect(toTree(out)).toEqual([
      { tag: 'p', attrs: {}, children: [{ text: 't' }] },
    ]);
