  // Default options keep <pre>/<script>/... contents as opaque raw text.
  const opts = { comment: true };
  const root = parse(html, opts);

  // Tags the parser will NOT expand into child elements. For these we take
  // the raw inner markup and parse it again so nested structure is visible.
  const OPAQUE = new Set(['pre', 'script', 'style', 'noscript', 'textarea', 'title']);

  function walk(node) {
    const out = [];
    for (const child of node.childNodes ?? []) {
      if (child.nodeType === NodeType.COMMENT_NODE) {
        out.push(null); // any surviving comment becomes visible in the tree
        continue;
      }
      if (child.nodeType === NodeType.TEXT_NODE) {
        if (child.text.trim() !== '') out.push({ text: child.text });
        continue;
      }
      if (child.nodeType !== NodeType.ELEMENT_NODE) continue;
      const attrs = {};
      for (const [k, v] of Object.entries(child.attributes ?? {})) attrs[k] = v;
      const tag = child.rawTagName.toLowerCase();
      const kids = OPAQUE.has(tag)
        ? walk(parse(child.rawText ?? '', opts))
        : walk(child);
      out.push({ tag, attrs, children: kids });
    }
    return out;
  }
  return walk(root);
}

